-- The guide's language (owner, Oct 16: chosen right away in the welcome window, the client's language preselected).
-- Each language ships as Locale/<code>.lua in this addon (the addon's own words, registered in ns.Locales and applied
-- once the saved settings load) and the BoFGuide_<code> addon (the route lines and names, loaded on demand). Quest,
-- item and place names always come from the game client. Generated by `forever guide-i18n` (docs/guide/i18n.md).
local _, ns = ...

local Lang = {}
ns.Lang = Lang
ns.Locales = ns.Locales or {}

-- the languages the guide speaks, each named in its own words, and the addon with its route lines (none for English)
Lang.LIST = {
  { code = 'enUS', name = 'English' },
  { code = 'deDE', name = 'Deutsch', addon = 'BoFGuide_deDE' },
  { code = 'esMX', name = 'Español', addon = 'BoFGuide_esMX' },
  { code = 'ptBR', name = 'Português', addon = 'BoFGuide_ptBR' },
  { code = 'frFR', name = 'Français', addon = 'BoFGuide_frFR' },
  { code = 'koKR', name = '한국어', addon = 'BoFGuide_koKR' },
}
-- the client's language -> the guide's
local CLIENT = { deDE = 'deDE', esES = 'esMX', esMX = 'esMX', ptBR = 'ptBR', ptPT = 'ptBR', frFR = 'frFR', koKR = 'koKR' }
-- the website's language folders that are live (all six languages since Oct 16; a new one is added the day the website
-- session says its site is up); any other language links the English page
local SITE = { deDE = 'de', esMX = 'es', ptBR = 'pt', frFR = 'fr', koKR = 'ko' }   -- (all five live, Oct 16)
local SITE_ROOT = 'https://bindonforever.com'
local current = 'enUS'

local function exists(addon)
  if not addon then return true end
  if C_AddOns and C_AddOns.DoesAddOnExist then return C_AddOns.DoesAddOnExist(addon) and true or false end
  local info = (C_AddOns and C_AddOns.GetAddOnInfo) or GetAddOnInfo
  if not info then return false end
  local ok, name, _, _, _, reason = pcall(info, addon)
  return ok and name ~= nil and reason ~= 'MISSING'
end

function Lang.Entry(code)
  for _, e in ipairs(Lang.LIST) do if e.code == code then return e end end
end

--- the languages installed: English, and each one with both its words and its route lines (Data/Lang_<code>.lua,
--- or an older separate addon). Kept from the first call: the ones not chosen are let go after login
local avail
function Lang.Available()
  if avail then return avail end
  avail = {}
  local client = GetLocale and GetLocale() or 'enUS'
  for _, e in ipairs(Lang.LIST) do
    -- (Korean only on a Korean client: the other clients' fonts have no Hangul, so it would show as empty boxes)
    local readable = e.code ~= 'koKR' or client == 'koKR'
    if e.code == 'enUS' or (readable and ns.Locales[e.code] and (ns.Packs.HasDeferred('Lang_' .. e.code) or exists(e.addon))) then
      avail[#avail + 1] = e
    end
  end
  return avail
end

--- the client's language when the guide speaks it, else English
function Lang.Default()
  local want = CLIENT[(GetLocale and GetLocale()) or 'enUS'] or 'enUS'
  for _, e in ipairs(Lang.Available()) do if e.code == want then return want end end
  return 'enUS'
end

function Lang.Current() return current end

-- each language's own words for the welcome window's Start button, kept before the other languages are let go: the
-- button speaks the language just clicked, so the player sees what the reload brings (owner, Oct 16)
local WELCOME_KEYS = { 'welcomeStart', 'welcomeSwitch' }
local welcome = {}

local function keepWelcome()
  local en = {}
  for _, k in ipairs(WELCOME_KEYS) do en[k] = ns.L[k] end
  welcome.enUS = en
  -- (a language file writes nested keys too, L["AUTO"]["accept"]: a table that makes its own sub-tables)
  local mt = {}
  mt.__index = function(t, k) local v = setmetatable({}, mt) rawset(t, k, v) return v end
  for code, fill in pairs(ns.Locales) do
    local t = setmetatable({}, mt)
    if pcall(fill, t) then
      local w = {}
      for _, k in ipairs(WELCOME_KEYS) do w[k] = type(rawget(t, k)) == 'string' and rawget(t, k) or en[k] end
      welcome[code] = w
    end
  end
end

--- a welcome-window word in a given language (English when that language lacks it)
function Lang.Word(code, key)
  return (welcome[code] or welcome.enUS or {})[key] or ns.L[key]
end

--- what happened at login, for /bofg language and the chat line when a language didn't load
Lang.why = nil

--- after the saved settings load: the chosen language's words now, its route lines as its addon loads
function Lang.Apply()
  local ok = {}
  for _, e in ipairs(Lang.Available()) do ok[e.code] = true end
  pcall(keepWelcome)   -- (never in the way of the language itself)
  local want = (ns.settings and ns.settings.lang) or Lang.Default()
  local code = want
  if not ok[code] then
    if code ~= 'enUS' then Lang.why = ('%s is not installed (no %s)'):format(code, ns.Locales[code] and 'route lines' or 'Locale file') end
    code = 'enUS'
  end
  current = code
  -- the names the game shows come from the client's language file when the guide has one (a German client reading
  -- the English guide still sees German names, and the Targets buttons find them); the lines from the chosen one
  local client = CLIENT[(GetLocale and GetLocale()) or 'enUS'] or 'enUS'
  local names = (client ~= 'enUS' and ns.Packs.HasDeferred('Lang_' .. client)) and client or 'enUS'
  if code == client then names = code end
  ns.Packs.Want(names, code)
  if code ~= 'enUS' then
    local done, err = pcall(ns.Locales[code], ns.L)
    if not done then Lang.why = code .. ': ' .. tostring(err) end
    if not ns.Packs.RunDeferred('Lang_' .. code) then        -- (its route lines: Data/, else an older addon)
      local loader = (C_AddOns and C_AddOns.LoadAddOn) or LoadAddOn
      if loader then pcall(loader, Lang.Entry(code).addon) end
    end
  end
  if names ~= code and names ~= 'enUS' then ns.Packs.RunDeferred('Lang_' .. names) end
  for k in pairs(ns.Locales) do ns.Locales[k] = nil end      -- (the other languages' words: let go)
end

--- choose a language: kept, and the interface reloads once when it changes what's on screen
function Lang.Set(code)
  if not Lang.Entry(code) then return false end
  ns.settings.lang = code
  if code ~= current then
    ns.Reload()
    return true
  end
  return false
end

--- a page of our website in the guide's language, when that language's site is up (else the English one)
function ns.SiteURL(path)
  local folder = SITE[current]
  return SITE_ROOT .. (folder and ('/' .. folder) or '') .. (path or '')
end
